result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/usercache.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getUser, clearCache } from './usercache.mjs';

test('concurrent calls for same id invoke fetcher only once', async () => {
  clearCache();
  let calls = 0;
  const fetcher = async () => {
    calls++;
    await new Promise((r) => setTimeout(r, 20));
    return { id: '42', name: 'Ada' };
  };

  const results = await Promise.all(
    Array.from({ length: 10 }, () => getUser('42', fetcher))
  );

  assert.equal(calls, 1);
  for (const user of results) assert.deepEqual(user, { id: '42', name: 'Ada' });
});

test('failed fetch is not cached; retry succeeds', async () => {
  clearCache();
  let attempts = 0;
  const flaky = async (id) => {
    attempts++;
    if (attempts === 1) throw new Error('boom');
    return { id, ok: true };
  };

  await assert.rejects(getUser('a', flaky), /boom/);
  assert.equal(attempts, 1);

  const user = await getUser('a', flaky);
  assert.deepEqual(user, { id: 'a', ok: true });
  assert.equal(attempts, 2);

  // success is now cached
  await getUser('a', flaky);
  assert.equal(attempts, 2);
});

test('different ids fetch independently', async () => {
  clearCache();
  const fetched = [];
  const fetcher = async (id) => {
    fetched.push(id);
    await new Promise((r) => setTimeout(r, 10));
    return { id };
  };

  const [a, b] = await Promise.all([getUser('x', fetcher), getUser('y', fetcher)]);
  assert.deepEqual(a, { id: 'x' });
  assert.deepEqual(b, { id: 'y' });
  assert.deepEqual(fetched.sort(), ['x', 'y']);

  // each id cached separately
  await Promise.all([getUser('x', fetcher), getUser('y', fetcher)]);
  assert.equal(fetched.length, 2);
});
"})
