result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/usercache.mjs", "content": "const cache = new Map();
export function getUser(id, fetcher) {
  if (cache.has(id)) return cache.get(id);
  const promise = fetcher(id).catch((err) => {
    // Don't let a failed fetch poison the cache: evict so later calls can retry.
    if (cache.get(id) === promise) cache.delete(id);
    throw err;
  });
  cache.set(id, promise);
  return promise;
}
export function clearCache() { cache.clear(); }
"})
